CREATE TABLE movies (movie_id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, language TEXT NOT NULL, genre TEXT NOT NULL, duration INTEGER NOT NULL, release_date TEXT NOT NULL, poster TEXT, trailer TEXT, rating REAL DEFAULT 0.0);
INSERT INTO "movies" VALUES(1,'Interstellar: Beyond Horizons','A team of courageous explorers travels through a newly discovered wormhole in space in an attempt to ensure humanity survival as Earth faces catastrophic collapse.','English','Sci-Fi',169,'2024-03-15T00:00:00','https://images.unsplash.com/photo-1534447677768-be436bb09401?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=zSWdZVtXT7E',3.6);
INSERT INTO "movies" VALUES(2,'Oppenheimer','The story of American scientist J. Robert Oppenheimer and his role in the development of the atomic bomb during World War II and the subsequent moral fallout.','English','Drama',180,'2024-04-10T00:00:00','https://images.unsplash.com/photo-1440404653325-ab127d49abc1?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=uYPbbksJxIg',3.9);
INSERT INTO "movies" VALUES(3,'Dune: Part Two','Paul Atreides unites with Chani and the Fremen while seeking revenge against the conspirators who destroyed his family and facing a choice between love and destiny.','English','Sci-Fi',166,'2024-05-01T00:00:00','https://images.unsplash.com/photo-1509198397868-475647b2a1e5?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=Way9Dexny3w',4.7);
INSERT INTO "movies" VALUES(4,'Spider-Man: Spider-Verse','Miles Morales catapults across the Multiverse, encountering a society of Spider-People charged with protecting its very existence.','English','Animation',140,'2024-06-15T00:00:00','https://images.unsplash.com/photo-1635805737707-575885ab0820?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=cqGjhVJWtEg',4.8);
INSERT INTO "movies" VALUES(5,'Leo: Bloody Sweet','A mild-mannered cafe owner gets caught up in a bloody confrontation with gangsters who believe he is a ruthless mobster from their past.','Tamil','Action',164,'2024-07-20T00:00:00','https://images.unsplash.com/photo-1517604931442-7e0c8ed2963c?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=Po3jVh2CAT8',4.3);
INSERT INTO "movies" VALUES(6,'Avatar: Fire and Ash','Jake Sully and Neytiri return in an exhilarating journey into new territories of Pandora, encountering the hostile Ash People in an epic struggle for survival.','English','Sci-Fi',175,'2026-12-18T00:00:00','https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=d9MyW72ELq0',0.0);
INSERT INTO "movies" VALUES(21,'spiderman1','action movie','English','Animation / Superhero',100,'2026-03-02T00:00:00','https://images.unsplash.com/photo-1604200213928-ba3cf4fc8436?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=TYMMOjBUPMM',4.5);
INSERT INTO "movies" VALUES(41,'sister','good movie','English','Family / Drama',100,'2026-09-02T00:00:00','https://images.unsplash.com/photo-1517604931442-7e0c8ed2963c?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=vVj4u_3n2H0',4.5);
INSERT INTO "movies" VALUES(61,'Remo','nice movie','tamil','Romance / Comedy',160,'2025-09-09T00:00:00','https://images.unsplash.com/photo-1536440136628-849c177e76a1?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=71_3q9uLg2U',4.5);
INSERT INTO "movies" VALUES(81,'Interseller1','feel good movie','English','Sci-Fi / Adventure',100,'2026-10-09T00:00:00','https://images.unsplash.com/photo-1534447677768-be436bb09401?w=600&auto=format&fit=crop','https://www.youtube.com/watch?v=zSWdZVtXT7E',3.6);
INSERT INTO "movies" VALUES(101,'The Dark Knight','When the menace known as the Joker wreaks havoc and chaos on Gotham City, Batman must accept one of the greatest psychological and physical tests of his ability to fight injustice.','English','Crime / Thriller',152,'2024-01-18T00:00:00','/static/images/posters/poster_dark_knight.jpg','https://www.youtube.com/watch?v=EXeTwQWrcwY',4.9);
INSERT INTO "movies" VALUES(102,'Inception','A skilled thief who steals corporate secrets through dream-sharing technology is given the inverse task of planting an idea into the mind of a C.E.O. in an intricate multi-layered subconscious heist.','English','Sci-Fi / Mystery',148,'2024-02-10T00:00:00','/static/images/posters/poster_inception.jpg','https://www.youtube.com/watch?v=YoHD9XEInc0',4.8);
INSERT INTO "movies" VALUES(103,'Avengers: Endgame','After the devastating cosmic events of Infinity War, the universe lies in ruins. With the help of remaining allies, the Avengers assemble once more in an ultimate showdown against Thanos.','English','Superhero / Action',181,'2024-03-22T00:00:00','/static/images/posters/poster_avengers.jpg','https://www.youtube.com/watch?v=TcMBFSGVi1c',4.8);
INSERT INTO "movies" VALUES(104,'Gladiator II','Years after witnessing the death of revered Maximus at the hands of his uncle, Lucius must enter the Colosseum after his home is conquered by tyrannical emperors ruling Rome with an iron fist.','English','Historical / Drama',148,'2024-11-15T00:00:00','/static/images/posters/poster_gladiator2.jpg','https://www.youtube.com/watch?v=4rgYUipGJNo',4.6);
INSERT INTO "movies" VALUES(105,'The Conjuring: Last Rites','Paranormal investigators Ed and Lorraine Warren take on one final terrifying case involving mysterious sinister demonic entities threatening an innocent family in a secluded countryside home.','English','Horror / Supernatural',112,'2024-04-12T00:00:00','/static/images/posters/poster_conjuring.jpg','https://www.youtube.com/watch?v=h9Q4zZS2v1k',4.3);
INSERT INTO "movies" VALUES(106,'La La Land','While navigating their blooming careers in modern Los Angeles, a passionate jazz pianist and an aspiring actress fall in love while attempting to reconcile their dreams for the future.','English','Romance / Musical',128,'2024-02-14T00:00:00','/static/images/posters/poster_lalaland.jpg','https://www.youtube.com/watch?v=0pdqf4P9MB8',4.7);
INSERT INTO "movies" VALUES(107,'Joker: Folie à Deux','Arthur Fleck is institutionalized at Arkham awaiting trial for his crimes as Joker. While struggling with his dual identity, Arthur not only stumbles upon true love, but also finds music.','English','Psychological / Thriller',138,'2024-10-04T00:00:00','/static/images/posters/poster_joker2.jpg','https://www.youtube.com/watch?v=_OKAwz2MsJs',4.2);
INSERT INTO "movies" VALUES(108,'Kalki 2898 AD','Set in a post-apocalyptic dystopian world in the year 2898 AD, a modern avatar of Vishnu descends to protect humanity from dark totalitarian forces in an epic mythological spectacle.','Telugu','Mythological / Sci-Fi',181,'2024-06-27T00:00:00','/static/images/posters/poster_kalki.jpg','https://www.youtube.com/watch?v=kQDd1AhGIHk',4.6);
INSERT INTO "movies" VALUES(109,'Jailer','A retired tiger-like jailer goes on a ruthless manhunt across cities to avenge his police officer son and dismantle a ruthless international antique smuggling syndicate.','Tamil','Action / Crime',168,'2024-08-10T00:00:00','/static/images/posters/poster_jailer.jpg','https://www.youtube.com/watch?v=Y5BeWdODPqo',4.6);
INSERT INTO "movies" VALUES(110,'Inside Out 2','Riley enters teenage years and Headquarters undergoes a sudden demolition to make room for unexpected new emotions: Anxiety, Envy, Ennui, and Embarrassment.','English','Animation / Family',96,'2024-06-14T00:00:00','/static/images/posters/poster_insideout2.jpg','https://www.youtube.com/watch?v=LEjhY15eCx0',4.8);
INSERT INTO "movies" VALUES(111,'Deadpool & Wolverine','The Time Variance Authority pulls a lethargic Wade Wilson from his quiet civilian life and thrusts him into a high-stakes multiverse mission alongside a grumpy Wolverine.','English','Comedy / Superhero',128,'2024-07-26T00:00:00','/static/images/posters/poster_deadpool.jpg','https://www.youtube.com/watch?v=73_1biulkYk',4.7);
INSERT INTO "movies" VALUES(112,'A Quiet Place: Day One','Experience the chilling day the world went quiet in New York City as terrifying sound-hunting extraterrestrial monsters descend upon Earth in complete mayhem.','English','Horror / Sci-Fi',99,'2024-06-28T00:00:00','/static/images/posters/poster_quietplace.jpg','https://www.youtube.com/watch?v=YPY7J-flzE8',4.3);
INSERT INTO "movies" VALUES(113,'Spirited Away','During her family move to the suburbs, a 10-year-old girl wanders into a magical world ruled by gods, spirits, and witches where humans are transformed into beasts.','Japanese','Fantasy / Adventure',125,'2024-01-05T00:00:00','/static/images/posters/poster_spiritedaway.jpg','https://www.youtube.com/watch?v=ByXuk9QqQkk',4.9);
INSERT INTO "movies" VALUES(114,'Knives Out: Glass Onion','World-famous detective Benoit Blanc travels to a private Greek island to peel back the layers of a mystery involving a quirky tech billionaire and his estranged circle of friends.','English','Mystery / Comedy',139,'2024-03-08T00:00:00','/static/images/posters/poster_knivesout.jpg','https://www.youtube.com/watch?v=gj5ibYSz8C8',4.4);
INSERT INTO "movies" VALUES(115,'Manjummel Boys','A tightly-knit group of friends from a small town in Kerala embark on a vacation trip to Kodaikanal, where one of them falls deep into the treacherous Guna Caves, triggering an extraordinary rescue.','Malayalam','Survival / Drama',135,'2024-02-22T00:00:00','/static/images/posters/poster_manjummel.jpg','https://www.youtube.com/watch?v=id848W91ySI',4.8);
CREATE TABLE reviews (review_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, movie_id INTEGER NOT NULL, rating REAL NOT NULL, review_text TEXT, sentiment_label TEXT, confidence_score REAL, review_date TEXT DEFAULT CURRENT_TIMESTAMP);
INSERT INTO "reviews" VALUES(1,2,1,5.0,'Exceptional cinematic experience with breathtaking sci-fi world-building, stellar sound design and spellbinding performances!','Positive',73.21,'2026-10-24 01:40:22');
INSERT INTO "reviews" VALUES(2,3,1,4.5,'Phenomenal storytelling and acting by Matthew McConaughey. Emotional, scientifically thrilling, and visually stunning on the big screen.','Positive',94.2,'2026-09-24T07:44:46.842000');
INSERT INTO "reviews" VALUES(3,4,1,3.0,'The scientific aspects were decent and visuals impressive, but the pacing felt a bit long and stretched out towards the third act.','Neutral',68.5,'2026-09-24T07:44:46.844000');
INSERT INTO "reviews" VALUES(4,5,1,2.0,'Too confusing and overly dramatic sound mixing made dialogues hard to understand. Not my cup of tea.','Negative',89.1,'2026-09-24T07:44:46.846000');
INSERT INTO "reviews" VALUES(5,2,2,5.0,'Oppenheimer is Christopher Nolan finest cinematic achievement. Cillian Murphy delivers an Oscar-worthy performance of rare depth and intensity.','Positive',81.22,'2026-09-24T14:00:51.013000');
INSERT INTO "reviews" VALUES(6,3,2,4.5,'Masterful direction, intense sound design, and razor sharp editing. A historic epic executed to perfection.','Positive',93.8,'2026-09-24T07:44:46.850000');
INSERT INTO "reviews" VALUES(7,4,2,3.5,'Very engaging history lesson with great performances, though dialogue heavy and slightly repetitive in the court hearing scenes.','Neutral',72.3,'2026-09-24T07:44:46.852000');
INSERT INTO "reviews" VALUES(8,5,2,2.5,'Disappointing and slow paced narrative. Expected more about the technical breakthroughs rather than bureaucratic hearings.','Negative',85.6,'2026-09-24T07:44:46.853000');
INSERT INTO "reviews" VALUES(9,2,3,5.0,'Dune Part Two is pure visual poetry. The worm-riding sequences and desert warfare are unmatched in cinema history. Astounding spectacle.','Positive',97.4,'2026-09-24T07:44:46.856000');
INSERT INTO "reviews" VALUES(10,3,3,4.0,'Incredible scale and world building. Austin Butler and Timothee Chalamet gave commanding performances.','Positive',91.5,'2026-09-24T07:44:46.858000');
INSERT INTO "reviews" VALUES(11,4,3,3.0,'Good production values but felt exhausting by the end due to its unrelenting volume and dark atmosphere.','Neutral',65.2,'2026-09-24T07:44:46.860000');
INSERT INTO "reviews" VALUES(12,2,4,5.0,'The animation styles and creativity blew my mind! Every single frame belongs in an art museum. Thrilling story and music.','Positive',97.8,'2026-09-24T07:44:46.862000');
INSERT INTO "reviews" VALUES(13,3,4,3.5,'Entertaining multiverse story with nice colors, though the cliffhanger ending was slightly abrupt.','Neutral',70.4,'2026-09-24T07:44:46.863000');
INSERT INTO "reviews" VALUES(14,4,5,4.5,'Thalapathy Vijay and Lokesh Kanagaraj delivered a high-octane action thriller! Anirudh background score elevated every fight scene.','Positive',95.1,'2026-09-24T07:44:46.865000');
INSERT INTO "reviews" VALUES(15,5,5,2.0,'Terrible second half with ridiculous plot logic and pointless flashback sequences. Completely wasted potential.','Negative',92.3,'2026-09-24T07:44:46.867000');
INSERT INTO "reviews" VALUES(16,2,6,5.0,'Spectacular Pandora world-building with breathtaking underwater visual effects and emotional family drama. James Cameron masterclass!','Positive',96.5,'2026-10-18T18:30:00');
INSERT INTO "reviews" VALUES(17,3,6,4.5,'Jaw-dropping CGI and stunning IMAX 3D action sequences that set a new benchmark for sci-fi cinema.','Positive',94.0,'2026-10-19T20:15:00');
INSERT INTO "reviews" VALUES(18,4,6,3.5,'Visually extraordinary and thrilling soundtrack, though the narrative pacing feels slightly prolonged in the middle act.','Neutral',71.2,'2026-10-20T14:00:00');
INSERT INTO "reviews" VALUES(19,2,21,4.5,'Exhilarating superhero adventure with amazing web-slinging action sequences, sharp humor, and delightful character chemistry.','Positive',92.4,'2026-10-19T16:20:00');
INSERT INTO "reviews" VALUES(20,3,21,4.0,'Fun comic-book adaptation with dazzling animated visuals and a great energetic soundtrack.','Positive',88.6,'2026-10-20T17:40:00');
INSERT INTO "reviews" VALUES(21,4,41,4.5,'Touching emotional drama with remarkable realistic performances by the lead cast and an inspiring storyline.','Positive',93.1,'2026-10-19T13:10:00');
INSERT INTO "reviews" VALUES(22,5,41,4.0,'Heartwarming family moments, lovely background score, and thoughtful direction throughout.','Positive',89.5,'2026-10-20T15:30:00');
INSERT INTO "reviews" VALUES(23,2,61,4.5,'Super fun romantic comedy! Sivakarthikeyan and Keerthy Suresh chemistry was delightful and Anirudh songs are super catchy.','Positive',95.0,'2026-10-19T21:00:00');
INSERT INTO "reviews" VALUES(24,3,61,4.0,'Charming lighthearted entertainer with humorous scenes, great colorful frames, and feel-good romance.','Positive',90.2,'2026-10-20T11:45:00');
INSERT INTO "reviews" VALUES(25,4,81,4.0,'Inspiring cosmic space exploration theme with philosophical concepts, beautiful nebula visuals, and great sound design.','Positive',91.8,'2026-10-20T19:00:00');
